#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-04

# worktree-config.sh: own this repo's generated .claude/settings.json: the
# native Claude Code worktree configuration plus the env keys pinned with it.
#
# Usage:
#   bin/worktree-config.sh --apply    # write .claude/settings.json
#   bin/worktree-config.sh --check    # verify the live config matches (exit 1 on drift)
#   bin/worktree-config.sh --list     # print the canonical symlink list, one per line
#   bin/worktree-config.sh --exempt   # print workspace roots deliberately not symlinked
#
# Why this script exists
#   .claude/settings.json is gitignored (.gitignore:152), so the live config
#   cannot be committed and cannot be diffed in review. The canonical list
#   therefore lives HERE, in a tracked file, and the settings file is generated
#   from it. tests/config/test-worktree-config.sh gates the list against the
#   repo's real workspace roots, so adding a workspace without deciding what
#   happens to its node_modules fails the build.
#
# What the config does (verified against the Claude Code 2.1.221 implementation,
# not just the docs):
#   For each entry, CC symlinks <main-repo>/<entry> -> <worktree>/<entry> when a
#   worktree is created. Entries containing "/" are joined with path.join, so
#   nested workspace roots are legal. Entries that are absolute or contain ".."
#   are rejected by CC. If the source does not exist in the main repository the
#   entry is skipped with a log line, never an error.
#
# Two more keys the same "cannot be committed" argument applies to (#3309):
#   worktree.baseRef  CC 2.1.133 added it (shared/cc-snapshots/2.1.133.md:5) with
#                     default "fresh", which branches new worktrees from
#                     origin/<default> and silently drops unpushed local commits.
#                     ork's agent-isolation pattern needs those commits visible, so
#                     this repo pins "head", the value
#                     src/skills/doctor/references/remediation-guide.md:100 names for
#                     project scope, and one of the two enum members CC accepts.
#   env.CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH
#                     CC 2.1.219 restored the nested-spawn default to 3
#                     (shared/cc-snapshots/2.1.219.md:28) after 2.1.217 dropped it
#                     to 1. Pinning "3" makes the depth-3 budget in chain-patterns
#                     Pattern 9 mechanical rather than advisory, and portable off
#                     this machine. doctor Check 16 reads .env.<VAR> from project
#                     scope, so a project pin counts.
#
# Deliberately NOT set here: autoCompactWindow. The key is real (integer
# 100000..1000000, "Auto-compact window size" in the 2.1.237 settings schema), but
# CC's own /autocompact writes it to userSettings, "auto" is expressed as the key
# being absent, CLAUDE_CODE_AUTO_COMPACT_WINDOW outranks it, and the correct value
# tracks the operator's model. A project-scope pin would impose one window on every
# contributor. It stays an operator-scope offer (doctor Check 16).
#
# Trade-off, stated plainly: symlinked worktrees SHARE one installed tree with
# the main repository. That is the point (5.2 GB -> 2.1 GB here) but worktrees
# stop being dependency-isolated. Two commands behave differently, and the
# difference was measured, not assumed:
#
#   npm install   SAFE. Replaces the symlink with a real directory in the
#                 worktree. The shared tree is untouched and nothing is written
#                 into it. The worktree quietly stops sharing, so re-run
#                 bin/worktree-reclaim.sh --apply to get the saving back.
#
#   npm ci        DESTRUCTIVE. Clears node_modules first and FOLLOWS the
#                 symlink: it empties the MAIN repository's tree and breaks
#                 every other worktree at once, while printing a normal
#                 "added N packages" success line.
#
# The dangerous-command-blocker hook denies `npm ci` when node_modules is a
# symlink, in every permission mode. If you remove that guard, remove these
# entries too.

set -euo pipefail

if ! REPO_ROOT=$(git rev-parse --show-toplevel); then
    echo "Error: not in a git repository" >&2
    exit 1
fi
SETTINGS="$REPO_ROOT/.claude/settings.json"

# ── Canonical list ────────────────────────────────────────────────────────────
# Every workspace root that gets a real `npm install`. Keep sorted so the
# generated JSON and the --check diff stay stable.
SYMLINK_DIRS=(
    "docs/site/node_modules"
    "node_modules"
    "orchestkit-demos/node_modules"
    "src/hooks/node_modules"
    "src/mcp-server/node_modules"
)

# Workspace roots deliberately NOT symlinked, with the reason. The test in
# tests/config/ requires every tracked package.json to appear in one list or the
# other, so a new workspace cannot be added silently.
#   docs/stubs/analytics-stub                        build-time stub, no install
#   packages/cli                                     published package, not installed here
#   packages/hook-contract                           published package, not installed here
#   packages/hook-contract/examples/generic-client   example, no install
#   plugins/ork/hooks                                generated by npm run build
#   tests/evals/scaffolds/typescript-nextjs          eval fixture, no install
EXEMPT_ROOTS=(
    "docs/stubs/analytics-stub"
    "packages/cli"
    "packages/hook-contract"
    "packages/hook-contract/examples/generic-client"
    "plugins/ork/hooks"
    "tests/evals/scaffolds/typescript-nextjs"
)

# Which ref new worktrees branch from. CC's enum is "fresh" | "head"; see the
# header for why this repo pins "head".
BASE_REF="head"

# Nested subagent spawn ceiling, pinned so it is enforced rather than conventional.
SPAWN_DEPTH="3"

cmd_list() {
    printf '%s\n' "${SYMLINK_DIRS[@]}"
}

cmd_exempt() {
    printf '%s\n' "${EXEMPT_ROOTS[@]}"
}

cmd_apply() {
    mkdir -p "$(dirname "$SETTINGS")"
    local existing='{}'
    if [[ -f "$SETTINGS" ]]; then
        # Preserve any other keys a human or another tool put there.
        existing=$(cat "$SETTINGS")
    fi
    printf '%s\n' "$existing" | jq \
        --argjson dirs "$(cmd_list | jq -R . | jq -s .)" \
        --arg base_ref "$BASE_REF" \
        --arg spawn_depth "$SPAWN_DEPTH" \
        '. * {
            worktree: ((.worktree // {}) + {symlinkDirectories: $dirs, baseRef: $base_ref}),
            env: ((.env // {}) + {CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH: $spawn_depth})
         }' \
        > "$SETTINGS.tmp"
    mv "$SETTINGS.tmp" "$SETTINGS"
    echo "Wrote $SETTINGS"
    cmd_list | sed 's/^/  + /'
    echo "  + worktree.baseRef = $BASE_REF"
    echo "  + env.CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH = $SPAWN_DEPTH"
}

cmd_check() {
    if [[ ! -f "$SETTINGS" ]]; then
        echo "FAIL: $SETTINGS does not exist. Run: bin/worktree-config.sh --apply" >&2
        return 1
    fi
    local configured expected delta drift=0
    configured=$(jq -r '.worktree.symlinkDirectories[]?' "$SETTINGS" | sort)
    expected=$(cmd_list | sort)
    if [[ "$configured" == "$expected" ]]; then
        echo "OK: worktree.symlinkDirectories matches the canonical list (${#SYMLINK_DIRS[@]} entries)"
    else
        drift=1
        delta=$(diff <(printf '%s\n' "$expected") <(printf '%s\n' "$configured") || :)
        {
            echo "FAIL: .claude/settings.json worktree.symlinkDirectories has drifted."
            printf '%s\n' "$delta" | sed 's/^/  /'
        } >&2
    fi

    # Scalar pins. `// ""` collapses "key absent" and "key wrong" into one report;
    # both need the same fix, and an absent key must not read as a pass.
    local live_base_ref live_spawn_depth
    live_base_ref=$(jq -r '.worktree.baseRef // ""' "$SETTINGS")
    live_spawn_depth=$(jq -r '.env.CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH // ""' "$SETTINGS")

    if [[ "$live_base_ref" == "$BASE_REF" ]]; then
        echo "OK: worktree.baseRef = $BASE_REF"
    else
        drift=1
        echo "FAIL: worktree.baseRef is '${live_base_ref:-<absent>}', expected '$BASE_REF'." >&2
    fi

    if [[ "$live_spawn_depth" == "$SPAWN_DEPTH" ]]; then
        echo "OK: env.CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH = $SPAWN_DEPTH"
    else
        drift=1
        echo "FAIL: env.CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH is '${live_spawn_depth:-<absent>}', expected '$SPAWN_DEPTH'." >&2
    fi

    if [[ "$drift" -ne 0 ]]; then
        echo "  Fix: bin/worktree-config.sh --apply" >&2
        return 1
    fi
    return 0
}

case "${1:---check}" in
    --apply)  cmd_apply ;;
    --check)  cmd_check ;;
    --list)   cmd_list ;;
    --exempt) cmd_exempt ;;
    -h|--help)
        sed -n '2,53p' "$0" | sed 's/^# \{0,1\}//'
        ;;
    *)
        echo "Unknown option: $1" >&2
        echo "Usage: $0 [--apply|--check|--list|--exempt]" >&2
        exit 1
        ;;
esac
